  assign c_tx_in_valid = full_TX_IN;
  assign c_tx_out_ready = ~avail_TX_OUT | (rd & hit[35]);
  assign c_rx_in_valid = full_RX_IN;
  assign c_rx_out_ready = ~avail_RX_OUT | (rd & hit[65]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_ev_am_err;
    irq_set[1] = c_ev_itb;
    irq_set[2] = c_ev_corr_a;
    irq_set[3] = c_ev_corr_b;
    irq_set[4] = c_ev_uncorr_a;
    irq_set[5] = c_ev_uncorr_b;
    irq_set[6] = c_ev_resync;
    irq_set[7] = full_TX_IN & c_tx_in_ready;
    irq_set[8] = wr & (hit[6] | hit[7] | hit[8] | hit[9] | hit[10] | hit[11] | hit[12] | hit[13] | hit[14]) & full_TX_IN;
    irq_set[9] = c_tx_out_valid & (~avail_TX_OUT | (rd & hit[35]));
    irq_set[10] = full_RX_IN & c_rx_in_ready;
    irq_set[11] = wr & (hit[36] | hit[37] | hit[38] | hit[39] | hit[40] | hit[41] | hit[42] | hit[43] | hit[44] | hit[45] | hit[46] | hit[47] | hit[48] | hit[49] | hit[50] | hit[51] | hit[52] | hit[53] | hit[54] | hit[55] | hit[56]) & full_RX_IN;
    irq_set[12] = c_rx_out_valid & (~avail_RX_OUT | (rd & hit[65]));
  end
  assign irq = |(irq_status & irq_enable);
  wire [3:0] flags = {avail_RX_OUT, full_RX_IN, avail_TX_OUT, full_TX_IN};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(h_TX_IN0);
