      10'd26: apb_rdata = 32'(h_TX_OUT11);
      10'd27: apb_rdata = 32'(h_TX_OUT12);
      10'd28: apb_rdata = 32'(h_TX_OUT13);
      10'd29: apb_rdata = 32'(h_TX_OUT14);
      10'd30: apb_rdata = 32'(h_TX_OUT15);
      10'd31: apb_rdata = 32'(h_TX_OUT16);
      10'd32: apb_rdata = 32'(h_TX_OUT17);
      10'd33: apb_rdata = 32'(h_TX_OUT18);
      10'd34: apb_rdata = 32'(h_TX_OUT19);
      10'd35: apb_rdata = 32'(h_TX_OUT20);
      10'd36: apb_rdata = 32'(h_RX_IN0);
      10'd37: apb_rdata = 32'(h_RX_IN1);
      10'd38: apb_rdata = 32'(h_RX_IN2);
      10'd39: apb_rdata = 32'(h_RX_IN3);
      10'd40: apb_rdata = 32'(h_RX_IN4);
      10'd41: apb_rdata = 32'(h_RX_IN5);
      10'd42: apb_rdata = 32'(h_RX_IN6);
      10'd43: apb_rdata = 32'(h_RX_IN7);
      10'd44: apb_rdata = 32'(h_RX_IN8);
