      10'd54: apb_rdata = 32'(h_RX_IN18);
      10'd55: apb_rdata = 32'(h_RX_IN19);
      10'd56: apb_rdata = 32'(h_RX_IN20);
      10'd57: apb_rdata = 32'(h_RX_OUT0);
      10'd58: apb_rdata = 32'(h_RX_OUT1);
      10'd59: apb_rdata = 32'(h_RX_OUT2);
      10'd60: apb_rdata = 32'(h_RX_OUT3);
      10'd61: apb_rdata = 32'(h_RX_OUT4);
      10'd62: apb_rdata = 32'(h_RX_OUT5);
      10'd63: apb_rdata = 32'(h_RX_OUT6);
      10'd64: apb_rdata = 32'(h_RX_OUT7);
      10'd65: apb_rdata = 32'(h_RX_OUT8);
      10'd66: apb_rdata = 32'({c_st_nsym_b, c_st_nsym_a, c_rx_am_sf, c_rx_am_lock});
      default: apb_rdata = '0;
